using System;using System.IO;using System.Linq;using System.Collections.Generic;using Mirror;using UnityEngine;using MultiFPS.Gameplay;
namespace ROM.Progression {
[Serializable]public sealed class RiftTradeSnapshot {public string Token,Other,Notice;public int Revision;public bool Incoming,Accepted,OwnConfirmed,OtherConfirmed;public List<RiftLootAxe> Own=new List<RiftLootAxe>(),OtherItems=new List<RiftLootAxe>(),Available=new List<RiftLootAxe>();}
public sealed partial class RiftJournalPlayer {
 public const float TradeRange=4; const double TradeTimeout=120; static long tradeSequence;
 sealed class Exchange {public string Token=Guid.NewGuid().ToString("N");public RiftJournalPlayer A,B;public bool Accepted,CA,CB;public int Revision;public double Until;public HashSet<string> OA=new HashSet<string>(),OB=new HashSet<string>();}
 Exchange exchange;double nextTradeRequest;
 bool TradeAlive=>isServer&&Player&&!Player.BOT&&Player.MyCharacter&&Player.MyCharacter.Health&&Player.MyCharacter.Health.CurrentHealth>0&&connectionToClient!=null&&connectionToClient.identity==netIdentity&&NetworkServer.connections.TryGetValue(connectionToClient.connectionId,out var c)&&c==connectionToClient;
 bool TradePair(RiftJournalPlayer other)=>other&&other!=this&&TradeAlive&&other.TradeAlive&&Ensure()&&other.Ensure()&&State.CharacterId!=other.State.CharacterId&&Player.MyCharacter.gameObject.scene==other.Player.MyCharacter.gameObject.scene&&Vector3.Distance(Player.MyCharacter.transform.position,other.Player.MyCharacter.transform.position)<=TradeRange;
 public bool TradeReserved(string id)=>exchange!=null&&(exchange.A==this?exchange.OA:exchange.OB).Contains(id);
 [Command]public void CmdRequestTrade(uint target){if(NetworkServer.spawned.TryGetValue(target,out var n))ServerRequestTrade(n.GetComponent<RiftJournalPlayer>());}
 [Server]public bool ServerRequestTrade(RiftJournalPlayer other){if(NetworkTime.time<nextTradeRequest)return false;nextTradeRequest=NetworkTime.time+1;if(exchange!=null||!TradePair(other)||other.exchange!=null)return false;exchange=other.exchange=new Exchange{A=this,B=other,Until=NetworkTime.time+TradeTimeout};TradeBroadcast();return true;}
 [Command]public void CmdAcceptTrade(string token){ServerAcceptTrade(token);}
 [Server]public bool ServerAcceptTrade(string token){var e=exchange;if(e==null||e.Token!=token||e.B!=this||e.Accepted||!TradePair(e.A))return false;e.Accepted=true;e.Revision++;e.Until=NetworkTime.time+TradeTimeout;TradeBroadcast();return true;}
 [Command]public void CmdTradeOffer(string token,int revision,string id,bool offered){ServerTradeOffer(token,revision,id,offered);}
 [Server]public bool ServerTradeOffer(string token,int revision,string id,bool offered){var e=exchange;if(e==null||e.Token!=token||!e.Accepted||e.Revision!=revision||!TradePair(e.A==this?e.B:e.A)||string.IsNullOrEmpty(id))return false;var item=State.LootAxes?.FirstOrDefault(x=>x.Id==id);if(item==null||State.LootAxes.Count(x=>x.Id==id)!=1||State.EquippedLootAxe==id)return false;var set=e.A==this?e.OA:e.OB;bool changed=offered?set.Add(id):set.Remove(id);if(!changed)return false;e.CA=e.CB=false;e.Revision++;e.Until=NetworkTime.time+TradeTimeout;TradeBroadcast();return true;}
 [Command]public void CmdConfirmTrade(string token,int revision){ServerConfirmTrade(token,revision);}
 [Server]public bool ServerConfirmTrade(string token,int revision){var e=exchange;if(e==null||e.Token!=token||!e.Accepted||e.Revision!=revision||!TradePair(e.A==this?e.B:e.A))return false;if(e.A==this){if(e.CA)return false;e.CA=true;}else{if(e.CB)return false;e.CB=true;}if(e.CA&&e.CB){if(!CommitTrade(e)){ServerCancelTrade();return false;}}else TradeBroadcast();return true;}
 bool CommitTrade(Exchange e){if(!e.A.TradePair(e.B)||e.A.path==e.B.path||e.OA.Count+e.OB.Count==0)return false;var a=e.A.State;var b=e.B.State;if(!ValidOffers(a,e.OA)||!ValidOffers(b,e.OB)||a.LootAxes.Any(x=>x==null)||b.LootAxes.Any(x=>x==null))return false;if(a.LootAxes.Count-e.OA.Count+e.OB.Count>MaximumLootAxes||b.LootAxes.Count-e.OB.Count+e.OA.Count>MaximumLootAxes)return false;var all=a.LootAxes.Concat(b.LootAxes).Select(x=>x.Id).ToArray();if(all.Distinct().Count()!=all.Length)return false;var na=JsonUtility.FromJson<JournalState>(JsonUtility.ToJson(a));var nb=JsonUtility.FromJson<JournalState>(JsonUtility.ToJson(b));var sentA=na.LootAxes.Where(x=>e.OA.Contains(x.Id)).ToArray();var sentB=nb.LootAxes.Where(x=>e.OB.Contains(x.Id)).ToArray();na.LootAxes.RemoveAll(x=>e.OA.Contains(x.Id));nb.LootAxes.RemoveAll(x=>e.OB.Contains(x.Id));na.LootAxes.AddRange(sentB);nb.LootAxes.AddRange(sentA);try{RiftTradePersistence.Commit(e.A.path,JsonUtility.ToJson(na),e.B.path,JsonUtility.ToJson(nb));}catch(Exception error){Debug.LogWarning("Trade not committed: "+error.Message);return false;}e.A.State=na;e.B.State=nb;e.A.exchange=e.B.exchange=null;e.A.Push("Intercambio completado");e.B.Push("Intercambio completado");e.A.TradeSend(null);e.B.TradeSend(null);tradeSequence++;return true;}
 static bool ValidOffers(JournalState s,HashSet<string> ids)=>s.LootAxes!=null&&ids.All(id=>id!=s.EquippedLootAxe&&s.LootAxes.Count(x=>x!=null&&x.Id==id)==1);
 [Command]public void CmdCancelTrade(string token){if(exchange!=null&&exchange.Token==token)ServerCancelTrade();}
 [Server]public void ServerCancelTrade(){var e=exchange;if(e==null)return;e.A.exchange=null;e.B.exchange=null;if(e.A)e.A.TradeSend(null);if(e.B)e.B.TradeSend(null);}
 void TradeTick(){if(exchange!=null&&(NetworkTime.time>exchange.Until||!TradePair(exchange.A==this?exchange.B:exchange.A)))ServerCancelTrade();}
 void TradeBroadcast(){var e=exchange;if(e==null)return;e.A.TradeSend(e);e.B.TradeSend(e);}
 void TradeSend(Exchange e){if(connectionToClient==null||!connectionToClient.isReady)return;if(e==null){TargetTrade(connectionToClient,"");return;}bool first=e.A==this;var other=first?e.B:e.A;var mine=first?e.OA:e.OB;var theirs=first?e.OB:e.OA;var snapshot=new RiftTradeSnapshot{Token=e.Token,Other=other.Player.PlayerInfo.Username,Revision=e.Revision,Incoming=!first&&!e.Accepted,Accepted=e.Accepted,OwnConfirmed=first?e.CA:e.CB,OtherConfirmed=first?e.CB:e.CA,Own=State.LootAxes.Where(x=>mine.Contains(x.Id)).ToList(),OtherItems=other.State.LootAxes.Where(x=>theirs.Contains(x.Id)).ToList(),Available=State.LootAxes.Where(x=>x.Id!=State.EquippedLootAxe).ToList(),Notice="Solo objetos · El intercambio de oro no está disponible en esta versión."};TargetTrade(connectionToClient,JsonUtility.ToJson(snapshot));}
 [TargetRpc]void TargetTrade(NetworkConnectionToClient target,string json){RiftTradeClient.Receive(json);}
}
public static class RiftTradeClient {public static RiftTradeSnapshot Current;public static event Action Changed;public static void Receive(string json){Current=string.IsNullOrEmpty(json)?null:JsonUtility.FromJson<RiftTradeSnapshot>(json);Changed?.Invoke();}}
// Durable two-journal commit point. Recovery is idempotent and runs before any journal write/load.
public static class RiftTradePersistence {
 [Serializable]sealed class Record {public string A,B,JA,JB;}
 static void Write(string path,string json){string tmp=path+".trade-tmp";File.WriteAllText(tmp,json);if(File.Exists(path))File.Replace(tmp,path,null);else File.Move(tmp,path);}
 public static void Recover(string root){if(string.IsNullOrEmpty(root)||!Directory.Exists(root))return;foreach(var file in Directory.GetFiles(root,"trade-*.pending")){var r=JsonUtility.FromJson<Record>(File.ReadAllText(file));if(r==null||Path.GetDirectoryName(r.A)!=root||Path.GetDirectoryName(r.B)!=root)throw new IOException("Invalid trade recovery record");Write(r.A,r.JA);Write(r.B,r.JB);File.Delete(file);}}
 public static void Commit(string a,string ja,string b,string jb){string root=Path.GetDirectoryName(a);if(a==b||Path.GetDirectoryName(b)!=root)throw new IOException("Trade storage mismatch");RiftVendorPersistence.Recover(root);Recover(root);string file=Path.Combine(root,"trade-"+Guid.NewGuid().ToString("N")+".pending");Write(file,JsonUtility.ToJson(new Record{A=a,B=b,JA=ja,JB=jb}));try{Recover(root);}catch(Exception e){Debug.LogWarning("Committed trade recovery pending: "+e.Message);}}
}
}
